"""VFDT: Very Fast Decision Tree (Hoeffding Tree) for high-speed data streams.

Reference: Domingos & Hulten, "Mining High-Speed Data Streams", KDD 2000.

The tree grows incrementally from a stream.  Every ``grace_period`` examples a
leaf tries to split: the two best attributes are compared and the split is
performed when the observed information gain difference is larger than the
Hoeffding bound

    epsilon = sqrt(R^2 * ln(1 / delta) / (2 n))

with R = log2(num_classes), delta = split_confidence and n the weight seen at
the leaf.  When epsilon drops below the tie threshold tau the split is forced,
which prevents the learner from stalling on (near) equally good attributes.
"""

import math
from typing import Dict, List, Optional, Sequence, Tuple

from attribute_observers import NominalAttributeObserver, NumericAttributeObserver
from classifiers import AbstractClassifier, compute_hoeffding_bound
from streams import Instance


class HoeffdingTreeNode:
    """Common base for leaves and split (internal) nodes."""

    def __init__(self, depth: int = 0):
        self.depth = depth
        self.class_counts: Dict[int, float] = {}

    # -- introspection -----------------------------------------------------
    def is_leaf(self) -> bool:
        raise NotImplementedError

    def total_weight(self) -> float:
        return sum(self.class_counts.values())

    def observed_class_distribution(self) -> Dict[int, float]:
        return dict(self.class_counts)

    def majority_class(self) -> int:
        if not self.class_counts:
            return 0
        best_class, best_count = 0, float('-inf')
        for cls in sorted(self.class_counts):
            count = self.class_counts[cls]
            if count > best_count:
                best_class, best_count = cls, count
        return best_class

    def is_pure(self) -> bool:
        """True when at most one class has been observed."""
        return sum(1 for c in self.class_counts.values() if c > 0) <= 1

    def update_class_counts(self, class_label: int, weight: float = 1.0):
        self.class_counts[class_label] = self.class_counts.get(class_label, 0.0) + weight


class HoeffdingTreeLeaf(HoeffdingTreeNode):
    """A learning leaf holding sufficient statistics for split decisions."""

    def __init__(self, num_classes: int = 2, depth: int = 0,
                 num_bins: int = 10, nominal_attributes: Optional[Sequence[int]] = None,
                 class_counts: Optional[Dict[int, float]] = None):
        super().__init__(depth)
        self.num_classes = num_classes
        self.num_bins = num_bins
        self.nominal_attributes = set(nominal_attributes or ())
        self.attribute_observers: Dict[int, object] = {}
        self.class_counts = dict(class_counts) if class_counts else {}
        self.weight_seen = float(sum(self.class_counts.values()))
        self.weight_at_last_split = self.weight_seen
        self.active = True

    def is_leaf(self) -> bool:
        return True

    # -- learning ----------------------------------------------------------
    def _observer_for(self, attr_index: int):
        observer = self.attribute_observers.get(attr_index)
        if observer is None:
            if attr_index in self.nominal_attributes:
                observer = NominalAttributeObserver()
            else:
                observer = NumericAttributeObserver(num_bins=self.num_bins)
            self.attribute_observers[attr_index] = observer
        return observer

    def learn_from_instance(self, instance: Instance, weight: float = 1.0):
        """Update the leaf statistics with a (possibly weighted) instance."""
        self.update_class_counts(instance.label, weight)
        self.weight_seen += weight
        if not self.active:
            return
        features = instance.features
        for attr_index in range(len(features)):
            self._observer_for(attr_index).observe(features[attr_index], instance.label, weight)

    def get_class_votes(self) -> Dict[int, float]:
        return dict(self.class_counts)

    def deactivate(self):
        """Stop collecting split statistics (memory management / max depth)."""
        self.active = False
        self.attribute_observers = {}

    # -- split search ------------------------------------------------------
    def get_best_split_suggestions(self, num_classes: int) -> List[Tuple[float, int, float, List[List[float]]]]:
        """Return ``(gain, attr_index, split_value, post_split_dists)`` per attribute."""
        suggestions = []
        for attr_index, observer in self.attribute_observers.items():
            gain, split_value, post = observer.get_best_split_suggestion(num_classes)
            if post:
                suggestions.append((gain, attr_index, split_value, post))
        suggestions.sort(key=lambda s: (s[0], -s[1]))
        return suggestions


class HoeffdingTreeSplit(HoeffdingTreeNode):
    """An internal node performing a binary test ``x[attr] < split_value``."""

    def __init__(self, split_attribute: int, split_value: float, depth: int = 0,
                 class_counts: Optional[Dict[int, float]] = None):
        super().__init__(depth)
        self.split_attribute = split_attribute
        self.split_value = split_value
        self.children: List[Optional[HoeffdingTreeNode]] = [None, None]
        self.class_counts = dict(class_counts) if class_counts else {}

    def is_leaf(self) -> bool:
        return False

    # -- routing -----------------------------------------------------------
    def branch_for_instance(self, instance: Instance) -> int:
        """0 == left branch (value < threshold), 1 == right branch."""
        value = instance.features[self.split_attribute]
        return 0 if value < self.split_value else 1

    def get_child(self, branch: int) -> Optional[HoeffdingTreeNode]:
        return self.children[branch]

    def set_child(self, branch: int, node: Optional[HoeffdingTreeNode]):
        self.children[branch] = node

    @property
    def left(self) -> Optional[HoeffdingTreeNode]:
        return self.children[0]

    @property
    def right(self) -> Optional[HoeffdingTreeNode]:
        return self.children[1]


class HoeffdingTree(AbstractClassifier):
    """Incremental decision tree learner (VFDT).

    Args:
        grace_period: instances a leaf must see between split attempts (n_min).
        split_confidence: 1 - probability of choosing the correct attribute (delta).
        tie_threshold: forced-split threshold on the Hoeffding bound (tau).
        max_depth: maximum tree depth; deeper leaves stop growing.
        num_classes: number of class labels (grows automatically if needed).
        num_attributes: number of attributes (inferred from the first instance).
        num_bins: bins used by the numeric attribute observers.
        nominal_attributes: indices handled with a nominal observer.
    """

    def __init__(self, grace_period: int = 200, split_confidence: float = 1e-7,
                 tie_threshold: float = 0.05, max_depth: int = 20,
                 num_classes: int = 2, num_attributes: Optional[int] = None,
                 num_bins: int = 10,
                 nominal_attributes: Optional[Sequence[int]] = None):
        super().__init__()
        self.grace_period = grace_period
        self.split_confidence = split_confidence
        self.tie_threshold = tie_threshold
        self.max_depth = max_depth
        self.num_classes = max(2, num_classes)
        self.num_attributes = num_attributes
        self.num_bins = num_bins
        self.nominal_attributes = set(nominal_attributes or ())
        self.num_splits = 0
        self.root: HoeffdingTreeNode = self._new_leaf(depth=0)

    # ------------------------------------------------------------------
    # construction helpers
    # ------------------------------------------------------------------
    def _new_leaf(self, depth: int = 0,
                  class_counts: Optional[Dict[int, float]] = None) -> HoeffdingTreeLeaf:
        return HoeffdingTreeLeaf(num_classes=self.num_classes, depth=depth,
                                 num_bins=self.num_bins,
                                 nominal_attributes=self.nominal_attributes,
                                 class_counts=class_counts)

    def reset(self):
        """Forget everything learned so far."""
        self.instances_seen = 0
        self.num_splits = 0
        self.root = self._new_leaf(depth=0)

    # ------------------------------------------------------------------
    # traversal
    # ------------------------------------------------------------------
    def _sort_to_leaf(self, instance: Instance
                      ) -> Tuple[HoeffdingTreeLeaf, Optional[HoeffdingTreeSplit], int]:
        """Return (leaf, parent_split_node, branch_index_in_parent)."""
        node = self.root
        parent: Optional[HoeffdingTreeSplit] = None
        branch = -1
        while not node.is_leaf():
            parent = node
            branch = node.branch_for_instance(instance)
            child = node.get_child(branch)
            if child is None:
                child = self._new_leaf(depth=node.depth + 1)
                node.set_child(branch, child)
            node = child
        return node, parent, branch

    def get_leaf(self, instance: Instance) -> HoeffdingTreeLeaf:
        """Public helper: the leaf an instance is sorted into."""
        return self._sort_to_leaf(instance)[0]

    # ------------------------------------------------------------------
    # training
    # ------------------------------------------------------------------
    def train(self, instance: Instance, weight: float = 1.0):
        """Update the tree with one training instance."""
        if weight <= 0:
            return
        if self.num_attributes is None:
            self.num_attributes = instance.num_attributes
        if instance.label >= self.num_classes:
            self.num_classes = instance.label + 1
        self.instances_seen += 1

        leaf, parent, branch = self._sort_to_leaf(instance)
        # internal nodes keep a coarse class distribution (used for pruning and
        # by CVFDT when a subtree gets replaced)
        node = self.root
        while not node.is_leaf():
            node.update_class_counts(instance.label, weight)
            node = node.get_child(node.branch_for_instance(instance))

        leaf.learn_from_instance(instance, weight)

        if leaf.active and leaf.weight_seen - leaf.weight_at_last_split >= self.grace_period:
            self._attempt_to_split(leaf, parent, branch)
            leaf.weight_at_last_split = leaf.weight_seen

    def partial_fit(self, instance: Instance, weight: float = 1.0):
        """Alias for :meth:`train` (scikit-multiflow style naming)."""
        self.train(instance, weight)

    # ------------------------------------------------------------------
    # splitting
    # ------------------------------------------------------------------
    def hoeffding_bound(self, n: float) -> float:
        """epsilon = sqrt(R^2 ln(1/delta) / 2n) with R = log2(num_classes)."""
        range_val = math.log2(self.num_classes) if self.num_classes > 1 else 1.0
        return compute_hoeffding_bound(range_val, self.split_confidence, n)

    def _attempt_to_split(self, leaf: HoeffdingTreeLeaf,
                          parent: Optional[HoeffdingTreeSplit], branch: int):
        if leaf.is_pure():
            return
        if leaf.depth >= self.max_depth:
            leaf.deactivate()
            return

        suggestions = leaf.get_best_split_suggestions(self.num_classes)
        if not suggestions:
            return

        best_gain, best_attr, best_value, best_post = suggestions[-1]
        # the "do not split" option always has gain 0 and acts as second best
        second_gain = suggestions[-2][0] if len(suggestions) > 1 else 0.0
        epsilon = self.hoeffding_bound(leaf.weight_seen)

        should_split = best_gain > 0.0 and (
            (best_gain - second_gain) > epsilon or epsilon < self.tie_threshold
        )
        if not should_split:
            return

        self._split_leaf(leaf, parent, branch, best_attr, best_value, best_post)

    def _make_split_node(self, leaf: HoeffdingTreeLeaf, attr: int, value: float,
                         post_split_dists: List[List[float]]) -> HoeffdingTreeSplit:
        split_node = HoeffdingTreeSplit(attr, value, depth=leaf.depth,
                                        class_counts=dict(leaf.class_counts))
        for branch_index in range(2):
            counts: Dict[int, float] = {}
            if branch_index < len(post_split_dists):
                for cls, cnt in enumerate(post_split_dists[branch_index]):
                    if cnt > 0:
                        counts[cls] = cnt
            child = self._new_leaf(depth=leaf.depth + 1, class_counts=counts)
            split_node.set_child(branch_index, child)
        return split_node

    def _split_leaf(self, leaf: HoeffdingTreeLeaf, parent: Optional[HoeffdingTreeSplit],
                    branch: int, attr: int, value: float,
                    post_split_dists: List[List[float]]):
        split_node = self._make_split_node(leaf, attr, value, post_split_dists)
        if parent is None:
            self.root = split_node
        else:
            parent.set_child(branch, split_node)
        self.num_splits += 1

    # ------------------------------------------------------------------
    # prediction
    # ------------------------------------------------------------------
    def get_votes(self, instance: Instance) -> Dict[int, float]:
        """Class vote distribution from the leaf the instance falls into."""
        node = self.root
        while not node.is_leaf():
            branch = node.branch_for_instance(instance)
            child = node.get_child(branch)
            if child is None:
                return node.observed_class_distribution()
            node = child
        return node.get_class_votes()

    def predict(self, instance: Instance) -> int:
        votes = self.get_votes(instance)
        if not votes:
            return 0
        best_class, best_count = 0, float('-inf')
        for cls in sorted(votes):
            if votes[cls] > best_count:
                best_class, best_count = cls, votes[cls]
        return best_class

    def predict_proba(self, instance: Instance) -> List[float]:
        votes = self.get_votes(instance)
        total = sum(votes.values())
        probs = [0.0] * self.num_classes
        if total <= 0:
            return probs
        for cls, cnt in votes.items():
            if cls < len(probs):
                probs[cls] = cnt / total
        return probs

    # ------------------------------------------------------------------
    # statistics
    # ------------------------------------------------------------------
    def get_tree_size(self) -> Dict[str, int]:
        """Return ``{'num_leaves', 'num_splits', 'total_nodes'}``."""
        num_leaves = 0
        num_splits = 0
        stack = [self.root]
        while stack:
            node = stack.pop()
            if node is None:
                continue
            if node.is_leaf():
                num_leaves += 1
            else:
                num_splits += 1
                stack.extend(node.children)
                stack.extend(getattr(node, 'alternate_trees', ()) or ())
        return {
            "num_leaves": num_leaves,
            "num_splits": num_splits,
            "total_nodes": num_leaves + num_splits,
        }

    def get_depth(self) -> int:
        max_depth = 0
        stack = [self.root]
        while stack:
            node = stack.pop()
            if node is None:
                continue
            max_depth = max(max_depth, node.depth)
            if not node.is_leaf():
                stack.extend(node.children)
        return max_depth

    def __str__(self) -> str:
        size = self.get_tree_size()
        return (f"HoeffdingTree(leaves={size['num_leaves']}, splits={size['num_splits']}, "
                f"depth={self.get_depth()}, instances={self.instances_seen})")


# Public alias: VFDT is the name used in the original paper.
VFDT = HoeffdingTree


class VFDTExperiment:
    """Experiment runner for the VFDT module."""

    def __init__(self, num_instances: int = 100000, window_size: int = 1000, seed: int = 42):
        self.num_instances = num_instances
        self.window_size = window_size
        self.seed = seed
        self.results: Dict[str, float] = {}

    def run_random_tree(self) -> Dict[str, float]:
        from evaluation import evaluate_prequential
        from streams import RandomTreeGenerator

        stream = RandomTreeGenerator(seed=self.seed, num_attributes=10,
                                     num_classes=2, max_depth=5)
        tree = HoeffdingTree(grace_period=200, split_confidence=1e-7,
                             tie_threshold=0.05, max_depth=20,
                             num_classes=stream.num_classes,
                             num_attributes=stream.num_attributes)
        metrics = evaluate_prequential(tree, stream, self.num_instances,
                                       window_size=self.window_size)
        size = tree.get_tree_size()
        self.results["VFDT_ACCURACY"] = metrics["cumulative_accuracy"]
        self.results["VFDT_TREE_NODES"] = size["total_nodes"]
        self.results["_window_accuracy"] = metrics["window_accuracy"]
        self.results["_num_leaves"] = size["num_leaves"]
        return self.results

    def run_all(self) -> Dict[str, float]:
        self.run_random_tree()
        return self.results

    def report(self):
        results = self.run_all()
        print(f"VFDT_ACCURACY: {results['VFDT_ACCURACY']:.4f}")
        print(f"VFDT_TREE_NODES: {int(results['VFDT_TREE_NODES'])}")


def main():
    VFDTExperiment().report()


if __name__ == "__main__":
    main()

